// Merge: DependenciesRegistry
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeDependenciesRegistry(
  dst: DependenciesRegistry,
  src: DependenciesRegistry,
): void {
  if (dst.gitlabProjectId === "") {
    dst.gitlabProjectId = src.gitlabProjectId;
  }
}
// ============================================================
// Merge: DependenciesConfig
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeDependenciesConfig(
  dst: DependenciesConfig,
  src: DependenciesConfig,
): void {
  if (!dst.registry && src.registry) {
    dst.registry = src.registry;
  } else if (dst.registry && src.registry) {
    mergeDependenciesRegistry(dst.registry, src.registry);
  }
}
